-- Australia Youth Worker profile.
-- Exact current occupation: OSCA 411733 Youth Worker, Skill Level 2.
-- Legacy ANZSCO 411716 is a migration correspondence but is split across current Youth Worker and Youth Justice Worker scopes.

update ingest.occupations_au
set shortage_rating = null, on_csol = true, median_salary_aud = null,
    confidence = 'official-profile-osl-csol',
    source_name = 'ABS OSCA 2024 v1.0 + JSA 2025 OSL + reviewed Home Affairs CSOL/ABS correspondence snapshot',
    source_url = 'https://www.abs.gov.au/statistics/classifications/osca-occupation-standard-classification-australia/2024-version-1-0/browse-classification/4/41/411/4117/411733',
    last_verified = '2026-08-09', anzsco_v13 = '411716'
where anzsco_code = '411733' and occupation_en = 'Youth Worker';

update ingest.visa_occupation_status_au
set reviewed_at = now(), reviewer_note = 'Reviewed OSCA 411733 Youth Worker correspondence to legacy ANZSCO 411716 in the current CSOL snapshot. Legacy 411716 also maps to OSCA 411732 Youth Justice Worker, so labour metrics are not treated as exact current Youth Worker observations.'
where osca_code = '411733' and anzsco_v13_code = '411716' and list_name = 'Core Skills Occupation List (CSOL)' and status = 'eligible';

update public.courses_au set official_course_url = 'https://www.rmit.edu.au/study-with-us/levels-of-study/undergraduate-study/bachelor-degrees/bachelor-of-youth-work-and-youth-studies-bp191', official_url_status = 'verified', official_url_checked_at = now(), official_url_source = 'Provider current international course page, verified 2026-08-09' where institution_id = 'rmit-university' and course_code = '098456B';
update public.courses_au set official_course_url = 'https://www.acu.edu.au/course/bachelor-of-youth-work', official_url_status = 'verified', official_url_checked_at = now(), official_url_source = 'Provider current course page/handbook, verified 2026-08-09' where institution_id = 'australian-catholic-university' and course_code = '084316G';

